mapper.select:
SELECT parent_id AS code, COUNT(*) AS cnt
FROM gb_device_channel
WHERE device_id = #{deviceId}
  AND parent_id IN
#{pid}
GROUP BY parent_id

SELECT id, device_id AS deviceId, channel_id AS channelId, report_name AS reportName, name, manufacturer, model, owner, civil_code AS civilCode, block, address, safety_way AS safetyWay, register_way AS registerWay, cert_num AS certNum, certifiable, secrecy, ip_address AS ipAddress, port, status, longitude, latitude, ptz_type AS ptzType, parent_id AS parentId, tree_path AS treePath, source FROM gb_device_channel WHERE device_id = #{deviceId} AND parental = 0
AND tree_path LIKE CONCAT(#{prefix}, '/%')
AND parent_id = #{parentId}
AND (name LIKE CONCAT('%', #{keyword}, '%') OR channel_id LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY tree_path
